import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

// Templates are generated by `vp run build:templates` from src/functions.
// These tests guard against the two most dangerous regressions in the
// generated, hand-deployed artifacts:
//   1. a token being posted to a wildcard (`"*"`) target origin, and
//   2. the artifact ceasing to be self-contained (an `import`/`require`).
const TEMPLATES = [fileURLToPath(new URL("../templates/auth.js", import.meta.url))];

describe("generated auth templates", () => {
    for (const path of TEMPLATES) {
        it(`is self-contained and never posts to "*" (${path})`, () => {
            expect(existsSync(path)).toBe(true);

            const code = readFileSync(path, "utf-8");

            expect(code).not.toMatch(/postMessage\(\s*message\s*,\s*"\*"\s*\)/);
            expect(code).not.toContain("import ");
            expect(code).not.toContain("require(");
        });
    }
});

// i18n workflow templates are shipped verbatim (placeholders filled by the
// init:i18n CLI). These tests assert the required placeholders survive in the
// source templates so the dist copy and the CLI substitution stay correct.
const I18N_TEMPLATES_DIR = fileURLToPath(new URL("../templates/i18n", import.meta.url));

const I18N_TEMPLATES = {
    workflow: fileURLToPath(
        new URL("../templates/i18n/i18n-translate.yml", import.meta.url),
    ),
    glossary: fileURLToPath(new URL("../templates/i18n/glossary.md", import.meta.url)),
    remap: fileURLToPath(
        new URL("../templates/i18n/remap-translations.sh", import.meta.url),
    ),
};

describe("i18n workflow templates", () => {
    it("all three i18n templates exist", () => {
        expect(existsSync(I18N_TEMPLATES.workflow)).toBe(true);
        expect(existsSync(I18N_TEMPLATES.glossary)).toBe(true);
        expect(existsSync(I18N_TEMPLATES.remap)).toBe(true);
        expect(existsSync(I18N_TEMPLATES_DIR)).toBe(true);
    });

    it("workflow template carries the substitution placeholders", () => {
        const content = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

        for (const token of [
            "__TEMPLATE_VERSION__",
            "__CONTENT_ROOT__",
            "__CONTENT_ROOT__/**/en/**",
            "__TARGET_LANGS__",
            "__CONFIG_FILE__",
            "__I18N_STRUCTURE__",
        ]) {
            expect(content).toContain(token);
        }

        // 0.4.0: per-file frontmatter flag replaces collection parsing.
        expect(content).toContain("autoTranslate: true");
        expect(content).toContain("OVERWRITE_MODE");
        expect(content).not.toContain("SKIP_COLLECTIONS");
        expect(content).not.toContain("__COLLECTION_EN_PATH__");

        // 0.4.1: GenAIScript only reads unprefixed / GENAISCRIPT_* env vars.
        // With-inputs alone (INPUT_OPENAI_API_KEY etc.) leave the provider
        // unconfigured, so the engine silently falls back to GitHub Models.
        expect(content).toContain("GENAISCRIPT_MODEL_TRANSLATION");
        expect(content).toContain("OPENAI_API_BASE");
        expect(content).toContain("TRANSLATION_MODEL");
        expect(content).toContain("Preflight translation credentials");
    });

    it("injects translation credentials as step env, not just with-inputs", () => {
        const content = readFileSync(I18N_TEMPLATES.workflow, "utf-8");
        const lines = content.split("\n");
        const translateAt = lines.findIndex((line) => line.includes("Translate chunk"));
        const withAt = lines.findIndex(
            (line, index) => index > translateAt && line.trim() === "with:",
        );

        expect(translateAt).toBeGreaterThan(-1);
        expect(withAt).toBeGreaterThan(translateAt);

        // The env block must sit between the step name and its `with:` block.
        const stepHead = lines.slice(translateAt, withAt).join("\n");
        expect(stepHead).toContain("OPENAI_API_KEY");
        expect(stepHead).toContain("GENAISCRIPT_MODEL_TRANSLATION");
        expect(stepHead).toContain("GENAISCRIPT_MODEL_VALIDATION");
    });

    it("every i18n template carries the version marker placeholder", () => {
        for (const path of Object.values(I18N_TEMPLATES)) {
            expect(readFileSync(path, "utf-8")).toContain(
                "astro-sveltia-pages i18n template v__TEMPLATE_VERSION__",
            );
        }
    });

    it("glossary template carries the project-name placeholder", () => {
        const content = readFileSync(I18N_TEMPLATES.glossary, "utf-8");
        expect(content).toContain("__PROJECT_NAME__");
    });

    it("remap script takes positional args and uses mv, not git mv", () => {
        const content = readFileSync(I18N_TEMPLATES.remap, "utf-8");
        expect(content).toContain("${1:");
        expect(content).toContain("${2:");
        // Staging files are untracked: `git mv` fails with "not under version control".
        expect(content).not.toContain("git mv");
        expect(content).toContain("mv -f");
        expect(content).toContain(".sources");
        expect(content).toContain("TARGET_LANGS");
    });
});

// 0.3.5 fixed a set of real CI failures in 0.3.4. Guard each one so a future
// "cleanup" cannot silently reintroduce them.
describe("i18n workflow 0.3.5 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

    it("uses a NON-hidden staging dir (GenAIScript skips dot directories)", () => {
        expect(workflow).toContain('STAGING_DIR: "i18n-staging"');
        expect(workflow).not.toContain(".i18n-staging");
    });

    it("never passes a raw /en/ source path to pelikhan", () => {
        expect(workflow).toContain("Stage EN sources (flatten locale dirs)");
        expect(workflow).toContain("files: ${{ steps.stage.outputs.stage_files }}");
    });

    it("reclaims Docker root-owned files and does no host-side mkdir", () => {
        expect(workflow).toContain("Reclaim ownership of Docker-generated files");
        expect(workflow).toContain("sudo chown -R");
        expect(workflow).not.toContain("mkdir -p .genaiscript");
    });

    it("fails loudly when no translations were produced", () => {
        expect(workflow).toContain("Verify translations were produced");
        expect(workflow).toContain("Fail when translation did not succeed");
        expect(workflow).toContain("exit 1");
    });

    it("pins the upstream action and uses the current DeepSeek model", () => {
        expect(workflow).toContain("pelikhan/action-continuous-translation@v0.2.11");
        // 0.4.1: model id lives in one env var, referenced by every alias.
        expect(workflow).toContain('TRANSLATION_MODEL: "deepseek-flash"');
        expect(workflow).toContain("openai:${{ env.TRANSLATION_MODEL }}");
        expect(workflow).not.toContain("deepseek-v4-flash");
        expect(workflow).toContain("filename_template:");
        expect(workflow).toContain("translations_dir:");
    });

    it("caches pelikhan's real incremental cache directory", () => {
        expect(workflow).toContain("path: i18n-translations");
    });

    it("keeps quoting on the `on` key for standard YAML parsers", () => {
        expect(workflow).toContain('"on":');
    });

    it("does not pre-seed staging with existing translations", () => {
        // pelikhan never reads target markdown; pre-seeded files would make the
        // zero-translation gate pass on a run that produced nothing.
        expect(workflow).not.toContain("CONTENT_ROOT/$coll/$L");
        expect(workflow).toContain("translationsDir/<lang>.json");
    });

    it("lowercases language codes when verifying produced filenames", () => {
        // pelikhan renders {{lang}} with to.toLowerCase(): zh-CN -> .zh-cn.md.
        expect(workflow).toContain("tr '[:upper:]' '[:lower:]'");
    });

    it("remap restores the original Sveltia locale casing", () => {
        const remap = readFileSync(I18N_TEMPLATES.remap, "utf-8");
        expect(remap).toContain("canonical_lang");
        expect(remap).toContain("tr '[:upper:]' '[:lower:]'");
        expect(remap).toContain('dest_lang="$(canonical_lang "$lang")"');
    });

    it("self-reports the template version in every Actions run", () => {
        expect(workflow).toContain("Verify i18n template version");
        expect(workflow).toContain("v__TEMPLATE_VERSION__");
        expect(workflow).toContain('TEMPLATE_VERSION: "__TEMPLATE_VERSION__"');
    });

    it("uses the same pnpm upgrade command in all three generated files", () => {
        for (const path of Object.values(I18N_TEMPLATES)) {
            const content = readFileSync(path, "utf-8");

            expect(content).toContain("pnpm exec astro-sveltia-pages init:i18n");
            expect(content).not.toContain("npx ");
        }
    });
});

// 0.4.2: DeepSeek occasionally echoed the upstream ┌T000┐ input markers instead
// of returning ```T000 fenced code regions. The engine parses only fences, saw
// "translations: 0", then replayed the same cached bad response 4 times. 0.4.1
// failed the whole job on the 2 missing languages and threw away the other 13.
describe("i18n workflow 0.4.2 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

    it("explicitly forbids echoing the box markers back", () => {
        expect(workflow).toContain("MANDATORY OUTPUT FORMAT");
        expect(workflow).toContain("NEVER echo");
        expect(workflow).toContain("┌T001┐");
        expect(workflow).toContain("fenced code region per HASH");
    });

    it("verifies softly first, then retries only the missing languages", () => {
        expect(workflow).toContain("Install translation verifier");
        expect(workflow).toContain('i18n-verify.sh" soft');
        expect(workflow).toContain("Prepare clean retry for missing languages");
        expect(workflow).toContain("Retry missing languages once");
        expect(workflow).toContain("lang: ${{ steps.verify.outputs.missing_langs }}");
        expect(workflow).toContain('i18n-verify.sh" hard');
        // The bad response must not be replayed from the prompt cache.
        expect(workflow).toContain("rm -rf .genaiscript");
        expect(workflow).toContain('rm -f "$TRANSLATIONS_DIR/$LL.json"');
        // Retry must be credentialed exactly like the first pass.
        expect(workflow).toContain("Reclaim ownership after retry");
    });

    it("never throws away the successful languages on one flaky language", () => {
        expect(workflow).toContain('ALLOW_PARTIAL_TRANSLATIONS: "true"');
        expect(workflow).toContain("ALLOW_PARTIAL_TRANSLATIONS=true");
        expect(workflow).toContain("GITHUB_STEP_SUMMARY");
        expect(workflow).not.toContain(
            '译文缺失 $(echo "$MISSING" | wc -w) 项，翻译引擎未产出完整结果。',
        );
    });

    it("asserts translations land in <collection>/<lang>/<slug>.md", () => {
        expect(workflow).toContain("Verify destination layout");
        expect(workflow).toContain('basename "$(dirname "$f")"');
        expect(workflow).toContain("$CONTENT_ROOT/blog/fr/<slug>.md");
        const remap = readFileSync(I18N_TEMPLATES.remap, "utf-8");
        expect(remap).toContain('basename "$dest_dir"');
        expect(remap).toContain("src/content/blog/fr/<slug>.md");
    });
});

// 0.4.3: `on.push.paths` also matches deleted paths. Deleting an EN post
// started the workflow, detect kept the now-missing path, and Stage failed with
// "源文件不存在" -> publish failed and opened a bogus issue.
describe("i18n workflow 0.4.3 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

    it("filters deleted/renamed EN paths before reading frontmatter", () => {
        expect(workflow).toContain(
            "reasons = { flag: 0, draft: 0, template: 0, deleted: 0 }",
        );
        expect(workflow).toContain("} else if (!fs.existsSync(f)) {");
        expect(workflow).toContain("源文件已删除/重命名");
        expect(workflow).toContain("已删除/重命名 ' + reasons.deleted");
        // Without this branch the missing file fell through to `keep.push(f)`.
        expect(workflow).toContain(
            "if (reason) console.log('跳过（' + reason + '）: ' + f);",
        );
    });

    it("tells the user that deleting EN does not remove published translations", () => {
        expect(workflow).toContain("其它语言目录下已发布的译文不会被自动删除");
        expect(workflow).toContain("本次变更仅包含 EN 文件删除");
    });

    it("handles first pushes and empty repositories without crashing detect", () => {
        expect(workflow).toContain(
            "const firstPush = before !== '' && /^0+$/.test(before);",
        );
        expect(workflow).toContain('git ls-files | grep -E "${re.source}" || true');
    });

    it("gives an actionable message if a missing source still reaches Stage", () => {
        expect(workflow).toContain("可能已在本次 push 中被删除/重命名");
        expect(workflow).toContain("升级工作流后重跑");
    });
});

// 0.4.4: 15 locales were translated successfully but the whole batch was lost
// because the FIRST push of i18n/batch-<run_id> rebased onto a remote ref that
// did not exist yet. The combined cache action also dropped those translations'
// incremental cache on any failed job, so a rerun paid for the model again.
describe("i18n workflow 0.4.4 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

    it("pushes a new batch branch directly instead of rebasing a missing ref", () => {
        expect(workflow).toContain('git rev-parse --verify "refs/remotes/origin/$BR"');
        expect(workflow).toContain('elif git push -u origin "$BR"; then');
        expect(workflow).toContain("git rebase --abort 2>/dev/null || true");
        // Concurrency path must stay intact for shards that arrive later.
        expect(workflow).toContain('git push --force-with-lease origin "$BR"');
    });

    it("saves the incremental cache even when publishing fails", () => {
        expect(workflow).toContain("uses: actions/cache/restore@v4");
        expect(workflow).toContain("uses: actions/cache/save@v4");
        expect(workflow).not.toContain("uses: actions/cache@v4");
        expect(workflow).toContain("Save translation cache");
        expect(workflow).toContain("steps.cache_check.outputs.has_files == 'true'");
        // An empty directory must never become the "most recent cache".
        expect(workflow).toContain('compgen -G "$TRANSLATIONS_DIR/*.json"');
        expect(workflow).toContain("continue-on-error: true");
    });

    it("documents where the cache lives and how to recover it", () => {
        expect(workflow).toContain("翻译缓存（i18n-translations/<lang>.json");
        expect(workflow).toContain("没有 Cache saved 就去该 run 页面下载");
        expect(workflow).toContain("translation-logs-<run_id>-<shard>");
        expect(workflow).toContain("兜底副本在 artifact");
    });

    it("names the first-push symptom in the failure issue", () => {
        expect(workflow).toContain("推送 batch 分支失败");
        expect(workflow).toContain("0.4.3 及更早模板");
    });
});

// 0.3.6 fixes the "upgraded the package, still running the 0.3.4 workflow"
// failure: the version check has to live in CI, not only in local commands.
describe("i18n workflow 0.3.6 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");

    it("compares the template version against the lockfile during detect", () => {
        expect(workflow).toContain("Verify i18n template version");
        expect(workflow).toContain("pnpm-lock.yaml");
        expect(workflow).toContain("process.env.TEMPLATE_VERSION");
        expect(workflow).toContain("process.exit(1)");
    });

    it("gives the exact fix command when the versions diverge", () => {
        expect(workflow).toContain("已安装的 astro-sveltia-pages 版本不一致");
        expect(workflow).toContain(
            "pnpm exec astro-sveltia-pages init:i18n（并提交更新后的三个文件）",
        );
    });

    it("names the two symptoms seen in the stale-workflow CI log", () => {
        expect(workflow).toContain("No files or not matching languages selected.");
        expect(workflow).toContain("mkdir .genaiscript/cache 权限失败");
    });

    it("isolates the translation cache per matrix shard", () => {
        expect(workflow).toContain(
            "key: i18n-${{ runner.os }}-${{ matrix.i }}-${{ github.run_id }}",
        );
        expect(workflow).toContain("i18n-${{ runner.os }}-${{ matrix.i }}-");
    });

    it("reports the template version in the failure issue", () => {
        expect(workflow).toContain("i18n 模板版本: v");
        expect(workflow).toContain("process.env.TEMPLATE_VERSION || ");
    });

    it("reads the declared-version fallback from the full match", () => {
        // That regex has no capture group: m[1] used to be undefined, which
        // silently disabled the whole check for manifests using `^0.3.x`.
        expect(workflow).toContain("installed = m[0]");
    });
});

describe("i18n workflow CMS UI locale parsing guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");
    const cli = readFileSync(
        fileURLToPath(new URL("../src/cli.ts", import.meta.url)),
        "utf-8",
    );

    it("keeps CLI and CI locale parsing on the same algorithm", () => {
        expect(cli).toContain("function extractLocalesBlock");
        expect(cli).toContain("function stripConfigComments");
        expect(cli).toContain("block.matchAll(/(?<![\\w])locale");
        expect(workflow).toContain("const localesBlock = s =>");
        expect(workflow).toContain("const parseLocales = s =>");
        expect(workflow).toContain("b.matchAll(/(?<![\\w])locale");
    });

    it("never falls back to a whole-file /locale:/ scan", () => {
        // That scan treated the CMS UI `locale: 'zh'` as the language list.
        expect(workflow).not.toContain("(?:^|[{,\\s])locale:");
        expect(cli).not.toContain("(?:^|[{,\\s])locale:");
    });

    it("fails loudly when locales omit default_locale", () => {
        expect(workflow).toContain("if (!locs.includes(dl[1]))");
        expect(cli).toContain("if (!rawLocales.includes(defaultLocale))");
    });

    it("auto-detects the shorter sveltia.config.mjs config name", () => {
        expect(cli).toContain('"sveltia.config.mjs"');
    });
});

// 0.4.5: translated commits used to be authored by a hardcoded bot identity,
// and `init:i18n` refused to run on classic YAML CMS configs.
describe("i18n workflow 0.4.5 regression guards", () => {
    const workflow = readFileSync(I18N_TEMPLATES.workflow, "utf-8");
    const cli = readFileSync(
        fileURLToPath(new URL("../src/cli.ts", import.meta.url)),
        "utf-8",
    );

    it("never hardcodes the i18n-bot commit identity", () => {
        expect(workflow).not.toContain("i18n-bot@users.noreply.github.com");
        expect(workflow).not.toContain('git config user.name "i18n-bot"');
    });

    it("exposes configurable author placeholders in the workflow env", () => {
        expect(workflow).toContain('COMMIT_AUTHOR_NAME: "__COMMIT_AUTHOR_NAME__"');
        expect(workflow).toContain('COMMIT_AUTHOR_EMAIL: "__COMMIT_AUTHOR_EMAIL__"');
        expect(cli).toContain("__COMMIT_AUTHOR_NAME__");
        expect(cli).toContain("resolveCommitAuthor");
    });

    it("falls back to the workflow triggerer in both commit steps", () => {
        expect(workflow).toContain('I18N_NAME="${COMMIT_AUTHOR_NAME:-$I18N_ACTOR}"');
        expect(workflow).toContain(
            "I18N_PUSHER_EMAIL: ${{ github.event.pusher.email }}",
        );
        // PR mode must use the same identity as commit mode.
        expect(workflow).toContain(
            'author: "${{ steps.merge.outputs.I18N_COMMIT_NAME }}',
        );
    });

    it("supports unquoted YAML CMS configs in both the CLI and CI validator", () => {
        expect(cli).toContain('"public/admin/config.yml"');
        expect(cli).toContain("YAML bare array");
        expect(workflow).toContain("YAML bare array: locales: [en, es, fr]");
        expect(workflow).toContain("c === '#'");
    });

    it("ships a postinstall hook that never breaks install", () => {
        expect(cli).toContain("runPostinstallI18n");
        expect(cli).toContain('args.includes("--postinstall")');
        expect(cli).toContain("I18N_POSTINSTALL_COMMAND");
        expect(cli).toContain('"--no-backup"');
    });
});
